df102['_has_ind_dev'] = df102['工业锅炉编号'].notna()

decisions = {}
for _, r in df102.iterrows():
    sid = ROW2SID[r['_row']]
    if r['_has_power_dev']:
        decisions[sid] = ('POWER', 'DEVICE_ELECTRIC_POWER_BOILER_OR_TURBINE')
    elif r['_has_ind_dev']:
        decisions[sid] = ('BOILER', 'DEVICE_INDUSTRIAL_BOILER')
    else:
