pow_src = df102[df102['_has_power_dev']].copy()
items = []

for _, src in pow_src.iterrows():
    sid = ROW2SID[src['_row']]
    org = str(src['组织机构代码'])
    low_nox = (str(src['是否采用低氮燃烧技术']).strip() == '是')
    ceffs = control_effs(org, low_nox)
    comps = [resolve_component(src, 'F1')]
    if pd.notna(src['燃料二类型']) and num(src['燃料二消耗量']) is not None:
        comps.append(resolve_component(src, 'F2'))
    if num(src['其他燃料消耗总量（吨标准煤）']) is not None:
        comps.append(resolve_component(src, 'OTH'))
    for poll in POLLUTANTS:
        gen = 0.0
        emi = 0.0
        comp_ok = True
        reasons = []
        act_rec = []
        par_rec = []
        ctl_rec = []
        for c in comps:
            cid = c['slot']
            act_rec.append({'component_id': cid, 'value': c['amount'], 'unit': c['unit']})
            if c.get('zero'):
                par_rec.append({'component_id': cid, 'parameter_id': 'EF_' + poll,
                                'mode': 'zero_activity', 'value': None, 'unit': c.get('per', 'g/kg')})
                ctl_rec.append({'component_id': cid, 'method': '无适用治理',
                                'efficiency': 0.0, 'fine_efficiency': 0.0, 'coarse_efficiency': 0.0})
                continue
            if not c.get('ok'):
                comp_ok = False
                reasons.extend(c.get('reasons', ['EF_UNAVAILABLE']))
                par_rec.append({'component_id': cid, 'parameter_id': 'EF_' + poll,
                                'mode': 'unavailable', 'value': None, 'unit': c.get('per', 'g/kg')})
                ctl_rec.append({'component_id': cid, 'method': '无适用治理（组件不可核算）',
                                'efficiency': 0.0, 'fine_efficiency': 0.0, 'coarse_efficiency': 0.0})
                continue
            ef = comp_ef(c, poll)
            if ef is None:
                comp_ok = False
                r = comp_ef_reason(c, poll)
                reasons.append(r if r else 'EF_UNAVAILABLE')
                par_rec.append({'component_id': cid, 'parameter_id': 'EF_' + poll,
                                'mode': 'unavailable', 'value': None, 'unit': c.get('per', 'g/kg')})
                ctl_rec.append({'component_id': cid, 'method': '无适用治理（组件不可核算）',
                                'efficiency': 0.0, 'fine_efficiency': 0.0, 'coarse_efficiency': 0.0})
                continue
            par = {'component_id': cid, 'parameter_id': 'EF_' + poll, 'mode': 'ef_table',
                   'value': round(ef, 6), 'unit': c.get('per', 'g/kg')}
            if poll == 'SO2' and c.get('so2_reason') is None and c.get('so2_sr') is not None:
                par['mode'] = 'material_balance_formula3'
                par['sulfur_content_pct'] = num(src['燃料一平均收到基含硫量'] if cid == 'F1' else src['燃料二平均收到基含硫量'])
                par['sulfur_to_bottom_ash_ratio'] = c['so2_sr']
            if poll in ('PM2.5', 'PM10', 'BC', 'OC') and c.get('pm_reason') is None and c.get('ar') is not None:
                par['mode'] = 'material_balance_formula4_6'
                par['ash_content_pct'] = num(src['燃料一平均收到基灰分（%）'] if cid == 'F1' else src['燃料二平均收到基灰分（%）'])
                par['ash_to_bottom_ash_ratio'] = c['ar']
                if poll in ('PM2.5', 'PM10'):
                    par['size_fraction_' + poll.replace('.', '_')] = c.get('f25' if poll == 'PM2.5' else 'f10')
                else:
                    par['fraction_of_pm25'] = c.get('fbc' if poll == 'BC' else 'foc')
            if poll == 'NOx' and c.get('nox_capacity_mw') is not None:
                par['installed_capacity_mw'] = c['nox_capacity_mw']
            par_rec.append(par)
            if poll == 'PM10':
                eff_f = ceffs['PM25']
                eff_c = ceffs['PM10C']
                f = c['pm25'] / c['pm10'] if c['pm10'] else 0.0
                eff_overall = (1 - (f * (1 - eff_f / 100.0) + (1 - f) * (1 - eff_c / 100.0))) * 100.0
                ctl = {'component_id': cid, 'method': ctl_method(ceffs, poll),
                       'efficiency': round(eff_overall, 4), 'fine_efficiency': round(eff_f, 4),
                       'coarse_efficiency': round(eff_c, 4)}
            else:
                eff = ceffs.get(poll, 0.0)
                ctl = {'component_id': cid, 'method': ctl_method(ceffs, poll),
                       'efficiency': round(eff, 4), 'fine_efficiency': round(eff, 4),
                       'coarse_efficiency': round(eff, 4)}
            ctl_rec.append(ctl)
            contrib = c['a_conv'] * ef / 1e6
            gen += contrib
            if poll == 'PM10':
                fine_part = c['a_conv'] * c['pm25'] / 1e6 * (1 - eff_f / 100.0)
                coarse_part = c['a_conv'] * (c['pm10'] - c['pm25']) / 1e6 * (1 - eff_c / 100.0)
                emi += fine_part + coarse_part
            else:
                emi += contrib * (1 - eff / 100.0)
        status = 'calculated' if comp_ok else 'information_insufficient'
        if not comp_ok and not reasons:
            reasons = ['EF_UNAVAILABLE']
        reason_str = ';'.join(sorted(set(reasons))) if reasons else 'CALC_OK'
        items.append({
            'source_id': sid, 'target': 'POWER', 'pollutant': poll, 'status': status,
            'method': method_of(poll, comps, status),
            'activity_record_json': json.dumps(act_rec, ensure_ascii=False),
            'parameter_record_json': json.dumps(par_rec, ensure_ascii=False),
            'control_record_json': json.dumps(ctl_rec, ensure_ascii=False),
            'generation_t': round(gen, 6), 'emission_t': round(emi, 6),
            'standard_reference': standard_ref(poll, comps, status), 'reason_code': reason_str,
        })

