def rep_sid(keyword):
    for r in idx['records']:
        sid = r['source_id']
        if decisions[sid][0] != 'POWER':
            continue
        src = df102[df102['_row'] == r['source_row']].iloc[0]
        dev = str(src['电站锅炉/燃气轮机类型']) if pd.notna(src['电站锅炉/燃气轮机类型']) else ''
        fuels = '|'.join(str(x) for x in [src['燃料一类型'], src['燃料二类型']] if pd.notna(x))
        if keyword in dev or keyword in fuels:
            return sid
    return next((r['source_id'] for r in idx['records'] if decisions[r['source_id']][0] == 'POWER'), '')


